<?php require_once 'functions.php'; $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT i.*,u.full_name,u.username FROM items i JOIN users u ON u.id=i.user_id WHERE i.id=?');$st->execute([$id]);$item=$st->fetch();if(!$item){http_response_code(404);page_header('Item not found');echo '<div class="empty">This report could not be found. <a href="index.php">Return to listings</a>.</div>';page_footer();exit;}
$claimError='';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['submit_claim'])){require_login();$message=trim($_POST['claim_message']??'');if((int)$item['user_id']===(int)$_SESSION['user']['id'])$claimError='You cannot submit a claim on your own report.';elseif($item['status']!=='active')$claimError='This report is no longer active.';elseif($message==='')$claimError='Please explain why you believe this item is yours.';else{$check=$pdo->prepare("SELECT id FROM claims WHERE item_id=? AND claimant_user_id=? AND claim_status='pending'");$check->execute([$id,$_SESSION['user']['id']]);if($check->fetch())$claimError='You already have a pending claim for this item.';else{$ins=$pdo->prepare('INSERT INTO claims(item_id,claimant_user_id,claim_message) VALUES(?,?,?)');$ins->execute([$id,$_SESSION['user']['id'],$message]);flash('Your claim has been submitted for review.');header('Location: item.php?id='.$id);exit;}}}
$claims=[];if(logged_in()&&((int)$item['user_id']===(int)$_SESSION['user']['id']||is_admin())){$cs=$pdo->prepare('SELECT c.*,u.full_name,u.email FROM claims c JOIN users u ON u.id=c.claimant_user_id WHERE c.item_id=? ORDER BY c.created_at DESC');$cs->execute([$id]);$claims=$cs->fetchAll();}
page_header('Item details'); ?><a class="back-link" href="index.php">← Back to listings</a><div class="detail-layout"><section class="panel detail-panel"><?php if($item['photo_path']): ?><img class="detail-photo" src="<?=e($item['photo_path'])?>" alt="Photo of <?=e($item['title'])?>"><?php else: ?><div class="detail-placeholder">✦</div><?php endif; ?><div class="card-top"><span class="pill <?=e($item['item_type'])?>"><?=e(ucfirst($item['item_type']))?></span><span class="pill neutral"><?=e($item['status'])?></span><span class="muted small"><?=e($item['category'])?></span></div><h1><?=e($item['title'])?></h1><p class="item-location">⌖ <?=e($item['place'])?></p><p class="muted">Date: <?=e($item['item_date'])?> · Posted by <?=e($item['full_name'])?></p><h3>Item description</h3><p class="detail-description"><?=nl2br(e($item['description']?:'No additional description was provided.'))?></p><div class="contact-box"><strong>Contact reporter</strong><p><?=e($item['contact_info'])?></p></div></section><aside class="panel claim-panel"><h2><?= $item['item_type']==='found'?'Is this yours?':'Have you found this item?' ?></h2><p class="muted">Send a claim with details that can help the reporter verify ownership.</p><?php if($claimError): ?><div class="alert error"><?=e($claimError)?></div><?php endif; ?><?php if(!logged_in()): ?><a class="button full" href="login.php">Log in to submit a claim</a><?php elseif((int)$item['user_id']===(int)$_SESSION['user']['id']): ?><p class="muted">This is your report.</p><?php elseif($item['status']!=='active'): ?><p class="muted">This report is closed.</p><?php else: ?><form method="post"><label>Why do you believe this item is yours? *<textarea name="claim_message" rows="5" required placeholder="Describe identifying details not shown in the listing…"></textarea></label><button class="button full" type="submit" name="submit_claim">Submit claim</button></form><?php endif; ?></aside></div>
<?php if($claims): ?><section class="panel claims-panel"><h2>Claims on this report</h2><?php foreach($claims as $c): ?><div class="claim-row"><div><strong><?=e($c['full_name'])?></strong> <span class="pill neutral"><?=e($c['claim_status'])?></span><p><?=nl2br(e($c['claim_message']))?></p><small><?=e($c['email'])?> · <?=e($c['created_at'])?></small></div><?php if(is_admin()): ?><form method="post" action="admin.php"><input type="hidden" name="claim_id" value="<?=(int)$c['id']?>"><input type="hidden" name="item_id" value="<?=$id?>"><button class="button small-button" name="claim_action" value="approved">Approve</button> <button class="button danger small-button" name="claim_action" value="rejected">Reject</button></form><?php endif; ?></div><?php endforeach; ?></section><?php endif; ?><?php page_footer(); ?>
